const I=(name,size='')=>`<i data-lucide="${name}" class="icon" ${size?`style="width:${size}px;height:${size}px"`:''}></i>`;
    const events=[
      {id:'agri',name:'มทส เกษตรแฟร์ 2569',date:'10–16 ก.พ. 2569',where:'ลานกิจกรรม มหาวิทยาลัยเทคโนโลยีสุรนารี',booths:'31',total:'96',org:'มหาวิทยาลัยเทคโนโลยีสุรนารี',type:'fair',tag:'งานแนะนำ',time:'09:00–21:00 น.',contact:'044-224-000',desc:'มหกรรมเกษตรและนวัตกรรมของ มทส รวมผลผลิตเกษตรอินทรีย์ ต้นไม้ อาหารท้องถิ่น และกิจกรรมเวิร์กช็อปสำหรับทุกคนในครอบครัว',zones:[{name:'โซนอาหารเกษตร',short:'Food Zone',free:'8',price:'฿500–1,200',total:'20',theme:'food',products:'อาหาร · เครื่องดื่ม · ของหวาน',desc:'จุดรวมอาหารแปรรูปและเครื่องดื่มจากเกษตรกร',prefix:'A',facility:'โต๊ะ 1 ตัว · เก้าอี้ 2 ตัว · ไฟฟ้า 1 จุด'},{name:'โซนผลผลิตเกษตร',short:'Farm Produce',free:'9',price:'฿450–900',total:'24',theme:'otop',products:'ผัก · ผลไม้ · เมล็ดพันธุ์',desc:'ผลผลิตสดและสินค้าทางการเกษตร',prefix:'B',facility:'โต๊ะ 1 ตัว · พื้นที่วางสินค้า'},{name:'โซนต้นไม้ & เกษตรอินทรีย์',short:'Plant & Organic',free:'10',price:'฿600–1,000',total:'28',theme:'workshop',products:'ต้นไม้ · อุปกรณ์ · อินทรีย์',desc:'ต้นไม้และผลิตภัณฑ์รักษ์โลก',prefix:'C',facility:'พื้นที่ 3 × 3 ม. · จุดน้ำใกล้เคียง'},{name:'โซนเวิร์กช็อป',short:'Workshop',free:'4',price:'฿800–1,500',total:'12',theme:'fashion',products:'กิจกรรม · งานคราฟต์',desc:'พื้นที่กิจกรรมสาธิตและเวิร์กช็อป',prefix:'D',facility:'โต๊ะ 2 ตัว · ไฟฟ้า 1 จุด'}]},
      {id:'silk',name:'งานผ้าไหมปักธงชัย 2569',date:'5–9 มี.ค. 2569',where:'อำเภอปักธงชัย จังหวัดนครราชสีมา',booths:'26',total:'72',org:'เครือข่ายผ้าไหมปักธงชัย',type:'violet',tag:'กำลังเปิดจอง',time:'10:00–20:00 น.',contact:'044-281-111',desc:'งานรวมผ้าไหมปักธงชัยจากช่างทอท้องถิ่น พร้อมแฟชั่นไหมร่วมสมัย สินค้า OTOP และกิจกรรมสาธิตการย้อมสีธรรมชาติ',zones:[{name:'โซนผ้าไหมทอมือ',short:'Handwoven Silk',free:'7',price:'฿700–1,500',total:'18',theme:'otop',products:'ผ้าไหม · ผ้าทอมือ',desc:'พื้นที่หลักสำหรับผู้ผลิตผ้าไหมและช่างทอ',prefix:'S',facility:'ราวแขวน · โต๊ะ · ไฟส่องสินค้า'},{name:'โซนแฟชั่นไหม',short:'Silk Fashion',free:'6',price:'฿800–1,600',total:'20',theme:'fashion',products:'เสื้อผ้า · เครื่องแต่งกาย',desc:'แฟชั่นและไลฟ์สไตล์จากผ้าไหม',prefix:'F',facility:'ราวแขวน · กระจก · ไฟฟ้า'},{name:'โซน OTOP & ของที่ระลึก',short:'OTOP Gift',free:'9',price:'฿500–1,100',total:'22',theme:'food',products:'OTOP · ของฝาก · หัตถกรรม',desc:'สินค้าชุมชนและของที่ระลึก',prefix:'O',facility:'โต๊ะ 1 ตัว · เก้าอี้ 2 ตัว'},{name:'โซนสาธิตย้อมสี',short:'Dye Workshop',free:'4',price:'฿900–1,400',total:'12',theme:'workshop',products:'เวิร์กช็อป · สีธรรมชาติ',desc:'กิจกรรมสาธิตและการเรียนรู้ผ้าไหม',prefix:'W',facility:'โต๊ะ 2 ตัว · จุดน้ำ · ไฟฟ้า'}]},
      {id:'campus',name:'SUT Green Market Weekend',date:'21–22 มี.ค. 2569',where:'อาคารสุรสัมมนาคาร มทส',booths:'18',total:'42',org:'SUT Student Affairs',type:'market',tag:'Upcoming',time:'10:00–20:00 น.',contact:'044-224-000',desc:'ตลาดสร้างสรรค์ประจำมหาวิทยาลัยสำหรับอาหาร สินค้าทำมือ และผลิตภัณฑ์ของนักศึกษา',zones:[{name:'โซนอาหาร',short:'Food',free:'8',price:'฿500–900',total:'20',theme:'food',products:'อาหาร · เครื่องดื่ม',desc:'ร้านอาหารและเครื่องดื่ม',prefix:'A',facility:'โต๊ะ · เก้าอี้ · ไฟฟ้า'},{name:'โซนเสื้อผ้า',short:'Fashion',free:'7',price:'฿600–1,000',total:'16',theme:'fashion',products:'เสื้อผ้า · ไลฟ์สไตล์',desc:'แฟชั่นและสินค้าทำมือ',prefix:'B',facility:'ราวแขวน · โต๊ะ'},{name:'โซนเวิร์กช็อป',short:'Workshop',free:'3',price:'฿800–1,200',total:'6',theme:'workshop',products:'กิจกรรม · คราฟต์',desc:'กิจกรรมเวิร์กช็อป',prefix:'C',facility:'โต๊ะ · ไฟฟ้า'}]}
    ];
    let page='home', selectedEvent=events[0], selectedZone=events[0].zones[0].name, selectedBooth='A15', modalOpen=false, toastTimer, activeBookingTab='payment';
    const vendorProfile={business:'อรุณ คาเฟ่',category:'อาหารและเครื่องดื่ม',peakTime:'11:00–14:00 น.',bookingScore:4.9,phone:'081-xxx-xxxx',email:'arun@example.com'};
    const currentZone=()=>selectedEvent.zones.find(z=>z.name===selectedZone)||selectedEvent.zones[0];
    function status(kind){const map={available:['ว่าง','available'],booked:['จองแล้ว','booked'],hold:['Hold 05:00','hold'],payment:['รอชำระเงิน','payment'],disabled:['ปิดใช้งาน','disabled'],confirmed:['ยืนยันแล้ว','available'],processing:['กำลังดำเนินการ','violet'],open:['เปิด','payment'],closed:['ปิด','disabled']};let v=map[kind]||map.disabled;return `<span class="badge ${v[1]}">${v[0]}</span>`}
    function eventCard(e,large=false){return `<article class="event-card ${large?'large':''}"><div class="event-img ${e.type}"><span class="badge violet" style="background:#ffffffdf">${e.tag}</span><span class="date"><b>${e.date.split(' ')[0]}</b>${e.date.split(' ').slice(1).join(' ')}</span></div><div class="event-body"><h3>${e.name}</h3><div class="event-meta">${I('map-pin')} ${e.where}</div><div class="org"><span class="org-dot">S</span>${e.org}</div><div class="event-footer"><b>เหลือ <span>${e.booths}</span> / ${e.total} บูธ</b><button class="btn secondary small" onclick="openEvent('${e.id}')">ดู Event</button></div></div></article>`}
    function shell(content){return `<div class="shell"><aside class="side"><div class="brand"><span class="brand-mark">${I('orbit')}</span>SpaceLink</div><span class="side-label">Explore</span><nav class="nav"><button class="${page==='home'?'active':''}" onclick="go('home')">${I('house')}หน้าหลัก</button><button class="${page==='discover'?'active':''}" onclick="go('discover')">${I('compass')}ค้นหา Event</button><button class="${['detail','zones','booths'].includes(page)?'active':''}" onclick="go('detail')">${I('calendar-days')}Event ที่แนะนำ</button></nav><span class="side-label">My Space</span><nav class="nav"><button class="${['bookings','bookingdetail','payment'].includes(page)?'active':''}" onclick="go('bookings')">${I('ticket')}การจองของฉัน</button><button class="${['support','ticket'].includes(page)?'active':''}" onclick="go('support')">${I('message-circle')}ช่วยเหลือ</button></nav><span class="side-label">Account</span><nav class="nav"><button class="${page==='profile'?'active':''}" onclick="go('profile')">${I('user-round')}โปรไฟล์</button></nav><div class="side-bottom"><div class="mini-profile"><span class="avatar">อ</span><div><b>อรุณ คาเฟ่</b><small>Vendor account</small></div></div></div></aside><main class="main"><header class="topbar"><div class="location">${I('map-pin')}<span>คุณกำลังค้นหาใน</span><b>นครราชสีมา</b></div><div class="top-actions"><button class="icon-btn" onclick="openNotifications()" aria-label="การแจ้งเตือน">${I('bell')}<i class="notification-dot"></i></button><button class="btn secondary small" onclick="go('profile')">อรุณ คาเฟ่</button></div></header>${content}</main></div><nav class="bottom-nav"><button class="${page==='home'?'active':''}" onclick="go('home')">${I('house')}<span>หน้าหลัก</span></button><button class="${page==='discover'?'active':''}" onclick="go('discover')">${I('compass')}<span>ค้นหา</span></button><button class="${['bookings','bookingdetail','payment'].includes(page)?'active':''}" onclick="go('bookings')">${I('ticket')}<span>การจอง</span></button><button class="${['support','ticket'].includes(page)?'active':''}" onclick="go('support')">${I('message-circle')}<span>ช่วยเหลือ</span></button><button class="${page==='profile'?'active':''}" onclick="go('profile')">${I('user-round')}<span>โปรไฟล์</span></button></nav>`}
    function title(eyebrow,h1,p,action=''){return `<div class="page-title"><div><span class="eyebrow">${eyebrow}</span><h1>${h1}</h1><p>${p}</p></div>${action}</div>`}
    function home(){return shell(`<div class="page"><section class="hero"><div class="hero-content"><span class="eyebrow" style="color:#F1E9FF;background:#ffffff1c">${I('sparkles')}พื้นที่ดี ๆ รออยู่</span><h1>จองบูธใน Event ที่ใช่<br>ให้ไอเดียของคุณได้เกิดขึ้น</h1><p>ค้นหา เลือกพื้นที่ และจองบูธได้ในที่เดียวสำหรับทุกงานที่คุณอยากไป</p><button class="btn primary" style="margin-top:20px;background:#fff;color:#5B21B6" onclick="go('discover')">Explore Event ${I('arrow-right')}</button></div></section><section class="search surface home-search"><div class="search-field"><label>ค้นหาสถานที่</label><select aria-label="ค้นหาสถานที่"><option value="">สถานที่ทั้งหมด</option><option>มหาวิทยาลัยเทคโนโลยีสุรนารี</option><option>ตลาดเซฟวัน โก</option><option>The Mall</option><option>Terminal 21</option><option>Central</option></select></div><div class="search-field"><label>จังหวัด</label><select aria-label="จังหวัด"><option value="">ทุกจังหวัด</option><option selected>นครราชสีมา</option><option>กรุงเทพมหานคร</option><option>บุรีรัมย์</option><option>ชลบุรี</option><option>สมุทรปราการ</option></select></div><div class="search-field"><label>ประเภทธุรกิจ</label><select aria-label="ประเภทธุรกิจ"><option value="">ทุกประเภทธุรกิจ</option><option>อาหาร / เครื่องดื่ม</option><option>เสื้อผ้า / แฟชั่น</option><option>ความงามและสุขภาพ</option><option>งานฝีมือ / ศิลปะและของสะสม</option><option>สัตว์เลี้ยง</option></select></div><button class="btn primary" onclick="go('discover')">${I('search')}<span>ค้นหา</span></button></section><section class="section"><div class="section-heading"><div><h2>Event ที่แนะนำสำหรับคุณ</h2><p>คัดจากประเภทธุรกิจและการจองล่าสุด</p></div><button class="btn ghost small" onclick="go('discover')">ดูทั้งหมด ${I('arrow-right')}</button></div><div class="event-grid">${events.map(e=>eventCard(e)).join('')}</div></section><section class="section home-split"><div class="surface" style="padding:20px"><div class="section-heading"><div><h2>การจองของฉัน</h2><p>ติดตามสถานะล่าสุดได้ที่นี่</p></div><button class="btn ghost small" onclick="go('bookings')">ทั้งหมด</button></div><div class="booking-row"><span class="booking-visual">${I('ticket')}</span><div><h4>SUT Green Market 2027 · Food Zone A15</h4><p>11–19 ม.ค. 2027 · ฿1,200</p></div>${status('payment')}<button class="btn outline small" onclick="go('payment')">ชำระเงิน</button></div><div class="booking-row"><span class="booking-visual">${I('store')}</span><div><h4>OTOP Winter Market · Zone B08</h4><p>12–14 ธ.ค. 2026 · ฿900</p></div>${status('confirmed')}<button class="btn outline small" onclick="go('bookingdetail')">รายละเอียด</button></div></div><aside class="help-card"><span class="eyebrow">${I('life-buoy')}Help Center</span><h3>ติดขัดเรื่องการจอง?</h3><p>ติดต่อผู้จัดงานโดยตรง หรือติดตามคำร้องขอย้ายบูธและคืนเงินได้ใน Support</p><button class="btn secondary" onclick="go('support')">ไปที่ Help Center ${I('arrow-up-right')}</button></aside></section></div>`) }
    function discover(){return shell(`<div class="page">${title('EXPLORE EVENTS','ค้นหา Event ที่เหมาะกับร้านคุณ','พบ 24 Event ที่กำลังเปิดรับจอง')}<section class="filter-bar surface"><input placeholder="ค้นหา Event, สถานที่ หรือผู้จัดงาน"><select><option>ทุกจังหวัด</option><option>นครราชสีมา</option></select><select><option>ประเภทงานทั้งหมด</option><option>Food Fair</option><option>Agriculture Fair</option><option>OTOP</option><option>Fashion</option><option>University Event</option><option>Market</option></select><select><option>วันที่จัดงาน</option><option>เดือนนี้</option><option>3 เดือนข้างหน้า</option></select><button class="btn primary" onclick="showToast('อัปเดตผลลัพธ์แล้ว')">${I('sliders-horizontal')}กรอง</button></section><div class="section-heading"><div><h2>กำลังเปิดรับจอง</h2><p>พื้นที่ว่างอัปเดตแบบเรียลไทม์</p></div><span class="badge violet">เรียงตาม: แนะนำ</span></div><div class="discover-grid">${events.map(e=>eventCard(e,true)).join('')}</div></div>`) }
    function detail(){return shell(`<div class="page">${title('EVENT DETAIL',selectedEvent.name,selectedEvent.date+' · '+selectedEvent.where,`<button class="btn primary" onclick="openEventTerms()">ดู Zone Map ${I('map')}</button>`)}<section class="detail-banner"><div><span class="badge violet" style="background:#ffffff25;color:#fff">กำลังเปิดจอง</span><h1>${selectedEvent.name}</h1><p>${I('calendar-days')} ${selectedEvent.date} &nbsp; ${I('map-pin')} ${selectedEvent.where}</p></div></section><section class="detail-layout"><div class="surface"><h2>เกี่ยวกับ Event นี้</h2><p>${selectedEvent.desc}</p><h2 style="margin-top:25px">พื้นที่ภายในงาน</h2><p>แผนผังแยก Zone ตามประเภทสินค้า เลือกโซนเพื่อดูบูธว่างและพื้นที่จริงก่อนจอง</p><div class="zone-preview">${selectedEvent.zones.map(z=>`<div class="zone-pill">${z.short}<small>${z.free} / ${z.total} บูธว่าง</small></div>`).join('')}</div><button class="btn primary" style="margin-top:18px" onclick="openEventTerms()">${I('map')} เลือกโซนและบูธ</button></div><aside class="surface"><h2>ข้อมูล Event</h2><div class="info-list"><div class="info-line"><span>${I('clock-3')}เวลา</span><b>${selectedEvent.time}</b></div><div class="info-line"><span>${I('building-2')}ผู้จัดงาน</span><b>${selectedEvent.org}</b></div><div class="info-line"><span>${I('phone')}ติดต่อ</span><b>${selectedEvent.contact}</b></div></div><div class="policy"><b>Event Policy</b><p>สินค้าต้องถูกกฎหมายและอยู่ในหมวดที่แต่ละ Zone อนุญาต</p></div><div class="policy"><b>Refund & Cancellation</b><p>การคืนเงินหลังยืนยันการจอง ดำเนินการผ่าน Support กับผู้จัดงาน</p></div></aside></section><section class="surface event-map-section"><div class="event-map-head"><div><span class="eyebrow">${I('map')} EVENT MAP</span><h2>แผนที่ภายในงาน</h2><p>ตรวจสอบตำแหน่งโซน ทางเข้า–ออก ห้องน้ำ ที่จอดรถ และจุดบริการก่อนเลือกบูธ</p></div><button class="btn primary" onclick="openEventTerms()">ดูแผนผังแบบเลือกได้ ${I('arrow-right')}</button></div><div class="event-map-frame"><img src="assets/event-detail-map.png" alt="แผนที่ ${selectedEvent.name}"></div></section></div>`) }
    function planSlots(zone){return Array.from({length:14},(_,i)=>`<span class="mini-booth" title="${zone.prefix}${String(i+1).padStart(2,'0')}"></span>`).join('')}
    function floorBoothCells(z){return [['01','booked','S'],['02','available','A'],['03','available','B'],['04','hold','A'],['05','available','A'],['06','payment','B'],['07','booked','S'],['08','available','C'],['09','disabled','C'],['10','available','A'],['11','booked','B'],['12','available','B'],['13','available','A'],['14','available','C'],['15','available','S'],['16','booked','A']].map(x=>[z.prefix+x[0],x[1],x[2]])}
    function zones(){let z=currentZone(),cells=floorBoothCells(z);return shell(`<div class="page">${title('EVENT FLOOR PLAN',selectedEvent.name,'อ่านกติกาแล้ว เลือก Zone และเลือก Booth ได้จากหน้าจอเดียว',`<button class="btn outline" onclick="go('detail')">${I('arrow-left')}กลับ Event</button>`)}<section class="map-layout"><div class="surface map-card"><div class="map-toolbar"><div><h2>แผนผังพื้นที่และบูธ</h2><p style="margin:2px 0 0;color:var(--muted);font-size:12px">กดโซนบนผัง หรือเลือกจาก dropdown ด้านล่าง</p></div><button class="btn secondary small" onclick="chooseZone(selectedEvent.zones[0].name);showToast('แนะนำโดยระบบสำรอง: '+selectedEvent.zones[0].short)">${I('sparkles')}แนะนำโซน</button></div><div class="legend">${status('available')}<span class="badge neutral">${I('mouse-pointer-click')} กดเลือก Zone</span><span class="badge neutral">${I('map-pin')} จุดบริการผู้เข้าชม</span></div><div class="plan-scroll"><div class="site-plan"><div class="plan-entry">${I('log-in')} ทางเข้า <small>· จุดลงทะเบียน</small></div>${selectedEvent.zones.map((zone,index)=>`<button class="plan-zone zone-${index} ${zone.theme} ${selectedZone===zone.name?'focused':''}" onclick="chooseZone('${zone.name}')"><span class="plan-count">${zone.free} ว่าง</span><h3>${zone.name}</h3><p>${zone.products}</p><div class="mini-booths">${planSlots(zone)}</div></button>`).join('')}<div class="plan-lane">ทางเดินกลาง 4 เมตร</div><div class="plan-service"><span>${I('circle-parking')} ที่จอดรถ</span><span>${I('accessibility')} สิ่งอำนวยความสะดวก</span><span>${I('cross')} ปฐมพยาบาล</span><span>${I('info')} ประชาสัมพันธ์</span><span>${I('bath')} ห้องน้ำ</span></div><div class="plan-exit">${I('log-out')} ทางออก <small>· จุดรับส่ง</small></div></div></div><section style="margin-top:20px;padding-top:18px;border-top:1px solid var(--line)"><div class="map-toolbar"><div><h2>เลือก Booth ใน ${z.short}</h2><p style="margin:2px 0 0;color:var(--muted);font-size:12px">เปลี่ยน Zone แล้วบูธและรหัสตำแหน่งจะอัปเดตทันที</p></div><span class="badge available">${z.free} บูธว่าง</span></div><div class="field" style="max-width:390px"><label>เลือก Zone เพื่อจอง</label><select aria-label="เลือก Zone เพื่อจอง" onchange="changeBookingZone(this.value)">${selectedEvent.zones.map(zone=>`<option value="${zone.name}" ${zone.name===selectedZone?'selected':''}>${zone.short} · ${zone.products}</option>`).join('')}</select></div><div class="legend">${status('available')}${status('booked')}${status('hold')}${status('payment')}${status('disabled')}</div><div class="booth-grid">${cells.map(x=>booth(...x)).join('')}</div></section></div><aside class="surface map-side"><span class="eyebrow">SELECTED ZONE</span><h2>${z.name}</h2><p>${z.desc}</p><div class="info-list"><div class="info-line"><span>บูธว่าง</span><b>${z.free} บูธ</b></div><div class="info-line"><span>ราคา</span><b>${z.price}</b></div><div class="info-line"><span>บูธทั้งหมด</span><b>${z.total} บูธ</b></div><div class="info-line"><span>ขนาดบูธ</span><b>3 × 3 ม.</b></div></div><div class="policy"><b>วิธีเลือกบูธ</b><p>แตะ Booth สีเขียวเพื่ออ่านรายละเอียด แล้วกด Select Booth เพื่อไปต่อ</p></div></aside></section></div>`) }
    function booth(name,kind,tier='A'){let z=currentZone();return `<button class="booth ${kind}" title="${kind==='available'?`กดเพื่อดูรายละเอียด · ${z.products}`:''}" onclick="${kind==='available'?`openBooth('${name}')`:''}">${name}<span class="tier ${tier.toLowerCase()}">Tier ${tier}</span><small>${kind==='available'?z.price.split('–')[0]:kind==='booked'?'Booked':kind==='hold'?'Hold':'Unavailable'}</small></button>`}
    function booths(){let z=currentZone(), cells=[['01','booked','S'],['02','available','A'],['03','available','B'],['04','hold','A'],['05','available','A'],['06','payment','B'],['07','booked','S'],['08','available','C'],['09','disabled','C'],['10','available','A'],['11','booked','B'],['12','available','B'],['13','available','A'],['14','available','C'],['15','available','S'],['16','booked','A']].map(x=>[z.prefix+x[0],x[1],x[2]]);return shell(`<div class="page">${title('BOOTH MAP',z.name,'เลือก Zone จากรายการ แล้วแผนผังบูธจะเปลี่ยนตามโซนที่เลือก',`<button class="btn outline" onclick="go('zones')">${I('arrow-left')}ดูทุกโซน</button>`)}<section class="map-layout"><div class="surface map-card"><div class="map-toolbar"><div><h2>${z.short} · Booth Map</h2><p style="margin:2px 0 0;color:var(--muted);font-size:12px">วางเมาส์หรือแตะบูธเพื่อดู Product type และราคา</p></div><span class="badge available">${z.free} บูธว่าง</span></div><div class="field" style="max-width:340px;margin:0 0 14px"><label>เลือก Zone เพื่อจอง</label><select aria-label="เลือก Zone เพื่อจอง" onchange="changeBookingZone(this.value)">${selectedEvent.zones.map(zone=>`<option value="${zone.name}" ${zone.name===selectedZone?'selected':''}>${zone.short} · ${zone.products}</option>`).join('')}</select></div><div class="legend">${status('available')}${status('booked')}${status('hold')}${status('payment')}${status('disabled')}</div><div class="booth-grid">${cells.map(x=>booth(...x)).join('')}</div></div><aside class="surface map-side"><span class="eyebrow">SELECTED FOR BOOKING</span><h2>${z.name}</h2><p>${z.desc}</p><div class="policy"><b>สิ่งอำนวยความสะดวก</b><p>${z.facility}</p></div><div class="policy"><b>สินค้าที่อนุญาต</b><p>${z.products}</p></div><div class="policy"><b>ราคา Zone นี้</b><p>${z.price} · ขนาด 3 × 3 เมตร</p></div></aside></section></div>`) }
    function booking(step=1){let confirm=step===2,z=currentZone();return shell(`<div class="page">${title('BOOK A BOOTH',confirm?'ยืนยันการจอง':'เลือกข้อมูลการจอง',confirm?'Hold ตำแหน่งนี้ไว้ให้คุณ 5 นาที':'ตรวจสอบประเภทสินค้าและวันเข้าร่วมงาน')}<div class="progress"><div class="progress-step done"><i class="progress-dot">1</i><span>เลือกบูธ</span></div><div class="progress-step ${confirm?'active':''}"><i class="progress-dot">2</i><span>ยืนยัน</span></div><div class="progress-step"><i class="progress-dot">3</i><span>ชำระเงิน</span></div><div class="progress-step"><i class="progress-dot">4</i><span>เสร็จสิ้น</span></div></div><section class="booking-layout"><div class="surface booking-panel">${confirm?confirmForm():bookingForm()}</div><aside class="surface summary"><h3>สรุปการจอง</h3><div class="summary-line"><span>Event</span><b>${selectedEvent.name}</b></div><div class="summary-line"><span>Zone / Booth</span><b>${z.short} / ${selectedBooth}</b></div><div class="summary-line"><span>วันที่</span><b>${selectedEvent.date}</b></div><div class="summary-line"><span>ขนาด</span><b>3 × 3 เมตร</b></div><div class="summary-line total"><span>รวมทั้งสิ้น</span><b>${z.price.split('–')[0]}</b></div></aside></section></div>`) }
    function bookingForm(){let z=currentZone();return `<h2>ข้อมูลร้านค้า</h2><p class="sub">${selectedEvent.name} · ${z.name}</p><div class="form-grid"><div class="field"><label>ชื่อร้าน</label><input value="อรุณ คาเฟ่"></div><div class="field"><label>หมวดสินค้า</label><select><option>${z.products}</option><option>หมวดอื่น ๆ ที่ผู้จัดงานอนุญาต</option></select></div><div class="field"><label>เบอร์โทรศัพท์</label><input value="081-xxx-xxxx"></div><div class="field"><label>วันที่เข้าร่วม</label><select><option>${selectedEvent.date}</option></select></div></div><div class="checks"><label class="check booking-rule-check"><input id="legal-product-check" type="checkbox" checked><span>สินค้าของฉันถูกกฎหมาย และอยู่ในหมวดที่ ${z.name} อนุญาต</span></label></div>`}
    function confirmForm(){return `<h2>ยืนยันการจอง</h2><p class="sub">ตรวจสอบรายละเอียดให้เรียบร้อยก่อนสร้างรายการจอง</p><div class="hold-box">${I('timer')}<div><b>Hold ล็อกตำแหน่งชั่วคราว</b><small style="display:block;color:#9B650B">ตำแหน่งจะถูกปล่อยเมื่อหมดเวลา</small></div><span class="timer" id="timer">05:00</span></div><div class="checks"><label class="check"><input type="checkbox" checked><span>ฉันยอมรับ <b>Event Policy</b> ของผู้จัดงาน</span></label><label class="check"><input type="checkbox" checked><span>สินค้าของฉันถูกกฎหมายและเป็นไปตามข้อกำหนด</span></label><label class="check"><input type="checkbox"><span>ฉันยอมรับ <b>Refund & Cancellation Policy</b></span></label></div><div style="display:flex;justify-content:space-between;gap:9px"><button class="btn danger" onclick="go('booths')">ยกเลิกการจอง</button><button class="btn primary" onclick="createBookingsAndPay()">Confirm Booking ${I('check')}</button></div>`}
    function payment(){return shell(`<div class="page">${title('WAITING PAYMENT','ชำระเงินสำหรับ Booking ของคุณ','รายการจองถูกสร้างแล้ว — ไม่มีเวลานับถอยหลังในขั้นตอนนี้')}<section class="booking-layout"><div class="surface booking-panel"><div class="payment-banner">${I('circle-dollar-sign')}<div><b>Waiting Payment</b><br><small>กรุณาชำระเงินและอัปโหลดหลักฐานเพื่อยืนยันการจอง</small></div>${status('payment')}</div><h2 style="text-align:center">สแกน QR เพื่อชำระเงิน</h2><p class="sub" style="text-align:center">ยอดชำระ ฿1,200.00</p><div class="qr" aria-label="ตัวอย่าง QR Payment"></div><div class="info-list"><div class="info-line"><span>ธนาคาร</span><b>กสิกรไทย</b></div><div class="info-line"><span>เลขบัญชี</span><b>123-4-56789-0</b></div><div class="info-line"><span>ชื่อบัญชี</span><b>SUT Student Affairs</b></div></div><div style="display:flex;justify-content:space-between;margin-top:19px"><button class="btn danger" onclick="showToast('ยกเลิกได้โดยไม่คืนเงินในสถานะรอชำระ')">Cancel Booking</button><button class="btn primary" onclick="go('upload')">Upload Slip ${I('upload')}</button></div></div><aside class="surface summary"><h3>Booking SL-260701</h3><div class="summary-line"><span>Event</span><b>SUT Green Market</b></div><div class="summary-line"><span>Booth</span><b>${selectedBooth} · Tier S</b></div><div class="summary-line"><span>สถานะ</span>${status('payment')}</div><div class="summary-line total"><span>ยอดชำระ</span><b>฿1,200</b></div></aside></section></div>`) }
    function upload(){return shell(`<div class="page">${title('UPLOAD PAYMENT SLIP','อัปโหลดหลักฐานการชำระเงิน','ส่งหลักฐานแล้ว รายการจองของคุณจะยืนยันทันที')}<section class="booking-layout"><div class="surface booking-panel"><h2>หลักฐานการชำระเงิน</h2><p class="sub">รองรับ JPG, PNG หรือ PDF ขนาดไม่เกิน 10 MB</p><button class="upload-area" style="width:100%;border-left:2px dashed #D8CEF3" onclick="showToast('เลือกไฟล์ Slip แล้ว')">${I('image-plus')}<div><b style="display:block;color:var(--ink);margin-top:7px">แตะเพื่อเลือกรูป Slip</b><span>หรือลากไฟล์มาวางบริเวณนี้</span></div></button><div class="form-grid" style="margin-top:17px"><div class="field"><label>วันที่และเวลาชำระ</label><input value="10 ม.ค. 2027 · 13:45"></div><div class="field"><label>จำนวนเงิน</label><input value="฿1,200.00"></div></div><button class="btn primary" style="margin-top:17px;width:100%" onclick="showToast('อัปโหลดสำเร็จ · การจองได้รับการยืนยันแล้ว');go('bookingdetail')">Confirm Upload ${I('check')}</button></div><aside class="surface summary"><h3>ชำระเงินให้ครบถ้วน</h3><p style="color:var(--muted);font-size:13px">ผู้จัดงานสามารถตรวจสอบ Slip ย้อนหลังได้ โดยสถานะการจองของคุณจะยืนยันทันทีหลังอัปโหลด</p><div class="payment-banner" style="margin-top:15px">${I('shield-check')}<small>ข้อมูลการชำระเงินของคุณถูกส่งอย่างปลอดภัย</small></div></aside></section></div>`) }
    const bookingItems=[
      {tab:'payment',icon:'utensils',name:'SUT Green Market 2027',detail:'Food Zone · A15 · 11–19 ม.ค. 2027',date:'10 ม.ค. 2027',badge:'payment',action:'payment'},
      {tab:'confirmed',icon:'shirt',name:'OTOP Winter Market',detail:'Fashion Zone · B08 · 12–14 ธ.ค. 2026',date:'20 พ.ย. 2026',badge:'confirmed',action:'bookingdetail'},
      {tab:'completed',icon:'coffee',name:'Korat Coffee Weekend',detail:'Food Zone · C04 · 2–3 พ.ย. 2026',date:'11 ต.ค. 2026',badge:'completed',action:'bookingdetail'},
      {tab:'cancelled',icon:'ban',name:'SUT Student Mini Fair',detail:'Student Zone · D09 · 18 ต.ค. 2026',date:'2 ต.ค. 2026',badge:'cancelled',action:'bookingdetail'}
    ];
    function bookingBadge(kind){if(kind==='completed')return '<span class="badge neutral">เสร็จสิ้น</span>';if(kind==='cancelled')return '<span class="badge booked">ยกเลิกแล้ว</span>';return status(kind)}
    function setBookingTab(tab){activeBookingTab=tab;render()}
    function bookings(){let items=bookingItems.filter(x=>x.tab===activeBookingTab);return shell(`<div class="page">${title('MY BOOKINGS','การจองของฉัน','ติดตามการจอง รายละเอียด และการชำระเงินของคุณ')}<div class="tabs"><button class="tab ${activeBookingTab==='payment'?'active':''}" onclick="setBookingTab('payment')">Waiting Payment</button><button class="tab ${activeBookingTab==='confirmed'?'active':''}" onclick="setBookingTab('confirmed')">Confirmed</button><button class="tab ${activeBookingTab==='completed'?'active':''}" onclick="setBookingTab('completed')">Completed</button><button class="tab ${activeBookingTab==='cancelled'?'active':''}" onclick="setBookingTab('cancelled')">Cancelled</button></div><div class="bookings-list">${items.length?items.map(x=>`<article class="surface my-booking"><span class="booking-visual">${I(x.icon)}</span><div><h3>${x.name}</h3><p>${x.detail}</p><p>Booking date: ${x.date}</p></div>${bookingBadge(x.badge)}<div class="booking-actions">${x.tab==='payment'?`<button class="btn primary small" onclick="go('payment')">ชำระเงิน</button>`:''}<button class="btn outline small" onclick="go('${x.action}')">รายละเอียด</button></div></article>`).join(''):`<div class="surface empty-state"><span class="empty-icon">${I('calendar-x')}</span><h3>ยังไม่มีรายการในสถานะนี้</h3><p>รายการจองของคุณจะแสดงที่นี่เมื่อสถานะเปลี่ยนแปลง</p></div>`}</div></div>`) }
    function support(){return shell(`<div class="page">${title('SUPPORT','ช่วยเหลือและคำร้อง','ติดต่อผู้จัดงานสำหรับการคืนเงิน ย้ายบูธ หรือสอบถามข้อมูล',`<button class="btn primary" onclick="openTicket('new')">${I('plus')}Create Ticket</button>`)}<section class="support-layout"><div class="surface" style="padding:18px"><div class="section-heading"><div><h2>คำร้องล่าสุด</h2><p>Vendor ↔ Organizer เท่านั้น</p></div></div><button class="ticket" onclick="go('ticket')"><div class="ticket-title"><h3>SUP-104 · ขอคืนเงินหลังยกเลิกการจอง</h3>${status('processing')}</div><p>SUT Green Market · SL-260701 · อัปเดต 10 นาทีที่แล้ว</p></button><button class="ticket" onclick="go('ticket')"><div class="ticket-title"><h3>SUP-099 · ขอเปลี่ยน Booth จาก A01 ไป A15</h3>${status('open')}</div><p>OTOP Winter Market · SL-260628 · อัปเดตเมื่อวานนี้</p></button><button class="ticket" onclick="go('ticket')"><div class="ticket-title"><h3>SUP-088 · สอบถามเวลาเข้าพื้นที่</h3>${status('closed')}</div><p>Korat Coffee Weekend · SL-260601 · ปิดคำร้องแล้ว</p></button></div><aside class="surface ticket-side"><span class="eyebrow">HELP CENTER</span><h3>เรื่องที่ช่วยได้</h3><div class="help-actions"><button onclick="openTicket('refund')"><span>Refund Request<small>ขอคืนเงินจากผู้จัดงาน</small></span>${I('chevron-right')}</button><button onclick="openTicket('change')"><span>Change Booth<small>ขอเปลี่ยนตำแหน่งบูธ</small></span>${I('chevron-right')}</button><button onclick="openTicket('problem')"><span>Report Problem<small>แจ้งปัญหาการใช้งานหรือหน้างาน</small></span>${I('chevron-right')}</button><button onclick="openTicket('contact')"><span>Contact Organizer<small>สอบถามข้อมูลกับผู้จัดงาน</small></span>${I('chevron-right')}</button></div><p style="margin-top:19px">การคืนเงินดำเนินการโดยผู้จัดงานนอกระบบ แต่ทุกการติดต่อจะถูกบันทึกไว้ที่นี่</p></aside></section></div>`) }
    function bookingDetail(){return shell(`<div class="page">${title('BOOKING DETAIL','SUT Green Market 2027','Booking ID: SL-260701',`<button class="btn outline" onclick="go('bookings')">${I('arrow-left')}การจองของฉัน</button>`)}<section class="booking-layout"><div class="surface booking-panel"><div style="display:flex;justify-content:space-between;align-items:center"><div><h2>Food Zone · Booth A15</h2><p class="sub" style="margin-bottom:0">11–19 มกราคม 2027</p></div>${status('confirmed')}</div><h2 style="margin-top:25px">Booking timeline</h2><div class="timeline"><div class="time-item"><div class="time-line"><span class="time-dot">✓</span></div><div><h4>ยืนยันการจองแล้ว</h4><p>อัปโหลด Slip สำเร็จ · 10 ม.ค. 2027, 13:48</p></div></div><div class="time-item"><div class="time-line"><span class="time-dot">✓</span></div><div><h4>สร้างรายการรอชำระเงิน</h4><p>10 ม.ค. 2027, 13:42</p></div></div><div class="time-item"><div class="time-line"><span class="time-dot">✓</span></div><div><h4>เลือก Booth A15</h4><p>Food Zone · Tier S · 3 × 3 เมตร</p></div></div></div><h2 style="margin-top:24px">ข้อมูลบูธและนโยบาย</h2><div class="info-list"><div class="info-line"><span>สิ่งอำนวยความสะดวก</span><b>โต๊ะ · เก้าอี้ · ไฟฟ้า</b></div><div class="info-line"><span>หมวดสินค้าที่อนุญาต</span><b>Food · Beverage</b></div><div class="info-line"><span>การชำระเงิน</span><b>฿1,200 · Slip uploaded</b></div></div></div><aside class="surface summary"><h3>ต้องการความช่วยเหลือ?</h3><p style="font-size:13px;color:var(--muted)">คำขอคืนเงินหรือย้ายบูธจะติดต่อกับผู้จัดงานผ่านระบบ Support</p><button class="btn secondary" style="width:100%;margin-top:15px" onclick="openTicket('refund')">Request Refund</button><button class="btn outline" style="width:100%;margin-top:8px" onclick="openTicket('contact')">Contact Organizer</button><div class="policy"><b>${I('phone')} 081-xxx-xxxx</b><p>ผู้จัดงาน SUT Student Affairs</p></div></aside></section></div>`) }
    function support(){return shell(`<div class="page">${title('SUPPORT','ช่วยเหลือและคำร้อง','ติดต่อผู้จัดงานสำหรับการคืนเงิน ย้ายบูธ หรือสอบถามข้อมูล',`<button class="btn primary" onclick="openTicket('new')">${I('plus')}Create Ticket</button>`)}<section class="support-layout"><div class="surface" style="padding:18px"><div class="section-heading"><div><h2>คำร้องล่าสุด</h2><p>Vendor ↔ Organizer เท่านั้น</p></div></div><button class="ticket" onclick="go('ticket')"><div class="ticket-title"><h3>SUP-104 · ขอคืนเงินหลังยกเลิกการจอง</h3>${status('processing')}</div><p>SUT Green Market · SL-260701 · อัปเดต 10 นาทีที่แล้ว</p></button><button class="ticket" onclick="go('ticket')"><div class="ticket-title"><h3>SUP-099 · ขอเปลี่ยน Booth จาก A01 ไป A15</h3>${status('open')}</div><p>OTOP Winter Market · SL-260628 · อัปเดตเมื่อวานนี้</p></button><button class="ticket" onclick="go('ticket')"><div class="ticket-title"><h3>SUP-088 · สอบถามเวลาเข้าพื้นที่</h3>${status('closed')}</div><p>Korat Coffee Weekend · SL-260601 · ปิดคำร้องแล้ว</p></button></div><aside class="surface ticket-side"><span class="eyebrow">HELP CENTER</span><h3>เรื่องที่ช่วยได้</h3><div class="info-list"><div class="info-line"><span>Refund Request</span>${I('chevron-right')}</div><div class="info-line"><span>Change Booth</span>${I('chevron-right')}</div><div class="info-line"><span>Report Problem</span>${I('chevron-right')}</div><div class="info-line"><span>Contact Organizer</span>${I('chevron-right')}</div></div><p style="margin-top:19px">การคืนเงินดำเนินการโดยผู้จัดงานนอกระบบ แต่ทุกการติดต่อจะถูกบันทึกไว้ที่นี่</p></aside></section></div>`) }
    function ticket(){return shell(`<div class="page">${title('SUPPORT TICKET','SUP-104 · ขอคืนเงินหลังยกเลิก','SUT Green Market · Booking SL-260701',`<button class="btn outline" onclick="go('support')">${I('arrow-left')}คำร้องทั้งหมด</button>`)}<section class="support-layout"><div class="surface" style="padding:20px"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px"><div><b>การสนทนากับผู้จัดงาน</b><small style="display:block;color:var(--muted)">สถานะคำร้อง ${status('processing')}</small></div></div><div class="thread"><div class="bubble"><b>อรุณ คาเฟ่</b><p>ต้องการยกเลิกการจอง และขอทราบเงื่อนไขการคืนเงินครับ</p><small>10:24</small></div><div class="bubble me"><b>SUT Student Affairs</b><p>รับเรื่องแล้วค่ะ กำลังตรวจสอบนโยบาย Event และรายการชำระเงินให้</p><small>10:42</small></div><div class="bubble"><b>อรุณ คาเฟ่</b><p>แนบ Slip และเหตุผลการยกเลิกเรียบร้อยครับ</p><small>10:58</small></div></div><div class="field" style="margin-top:16px"><label>ตอบกลับผู้จัดงาน</label><textarea rows="3" placeholder="พิมพ์ข้อความ..."></textarea></div><button class="btn primary" style="margin-top:9px" onclick="showToast('ส่งข้อความแล้ว')">ส่งข้อความ ${I('send')}</button></div><aside class="surface ticket-side"><h3>รายละเอียดคำร้อง</h3><div class="info-list"><div class="info-line"><span>ประเภท</span><b>Refund Request</b></div><div class="info-line"><span>สถานะ</span>${status('processing')}</div><div class="info-line"><span>ผู้จัดงาน</span><b>SUT</b></div><div class="info-line"><span>การคืนเงิน</span><b>นอกระบบ</b></div></div></aside></section></div>`) }
    function profile(){return shell(`<div class="page">${title('PROFILE','โปรไฟล์ของฉัน','จัดการข้อมูลร้านค้าและประวัติการจอง',`<button class="btn outline" onclick="openEditProfile()">${I('pencil')}Edit Profile</button>`)}<section class="profile-layout"><aside class="surface profile-card"><span class="profile-avatar">${vendorProfile.business.charAt(0)}</span><div><h2>${vendorProfile.business}</h2><p>Vendor since 2025</p></div><div class="score"><div><b>4.9</b><span>Vendor Score</span></div><div><b>0</b><span>Blacklist Point</span></div></div></aside><section class="surface profile-details"><h2>ข้อมูลติดต่อ</h2><div class="info-list"><div class="info-line"><span>${I('user-round')}ชื่อร้าน</span><b>${vendorProfile.business}</b></div><div class="info-line"><span>${I('phone')}เบอร์โทรศัพท์</span><b>${vendorProfile.phone}</b></div><div class="info-line"><span>${I('mail')}อีเมล</span><b>${vendorProfile.email}</b></div><div class="info-line"><span>${I('tags')}ประเภทธุรกิจ</span><b>${vendorProfile.category}</b></div></div><h2 style="margin-top:25px">Booking History</h2><div class="booking-row"><span class="booking-visual">${I('ticket')}</span><div><h4>การจองทั้งหมด</h4><p>ตั้งแต่เริ่มใช้งาน SpaceLink</p></div><b style="margin-left:auto">12 รายการ</b></div><div class="booking-row"><span class="booking-visual">${I('star')}</span><div><h4>คะแนน Vendor</h4><p>คะแนนจากผู้จัดงาน</p></div><b style="margin-left:auto;color:#6633C4">Excellent</b></div></section></section></div>`) }
    function render(){const pages={home,discover,detail,zones,booths,booking:()=>booking(1),confirm:()=>booking(2),payment,upload,bookings,bookingdetail:bookingDetail,support,ticket,profile};document.getElementById('app').innerHTML=(pages[page]||home)();if(window.lucide)lucide.createIcons();document.querySelectorAll('button').forEach(b=>{if(b.textContent.includes('แนะนำโซน'))b.onclick=()=>openZoneRecommendation()});if(page==='confirm')startTimer()}
    function go(next){page=next;window.scrollTo({top:0,behavior:'smooth'});render()}
    function openEvent(id){selectedEvent=events.find(e=>e.id===id)||events[0];selectedZone=selectedEvent.zones[0].name;selectedBooth=selectedEvent.zones[0].prefix+'15';go('detail')}
    function chooseZone(name){selectedZone=name;render()}
    function changeBookingZone(name){selectedZone=name;selectedBooth=currentZone().prefix+'15';render()}
    function zoneRanking(){let baseTraffic=[95,90,82,76];return selectedEvent.zones.map((zone,index)=>{let productFit=/อาหาร|เครื่องดื่ม|ของหวาน/.test(zone.products);let traffic=baseTraffic[index]||72;let score=productFit?Math.min(98,traffic+3):traffic;return {zone,score,traffic,productFit,peak:traffic>=90?'คนเดินผ่านหนาแน่น':'คนเดินผ่านสม่ำเสมอ'} }).sort((a,b)=>b.score-a.score)}
    function openZoneRecommendation(){let ranked=zoneRanking(),best=ranked[0];document.getElementById('modal').innerHTML=`<div class="modal-back" onclick="closeModal(event)"><section class="modal" onclick="event.stopPropagation()"><div class="modal-head"><div><span class="eyebrow">SMART ZONE MATCH</span><h2>โซนที่เหมาะกับร้านคุณ</h2></div><button class="close" aria-label="ปิด" onclick="closeModal()">${I('x')}</button></div><p style="margin-top:7px">วิเคราะห์จากโปรไฟล์ <b>${vendorProfile.business}</b> · ${vendorProfile.category} และรูปแบบการเดินของผู้เข้าชมในงาน</p><div style="margin:16px 0;border:1px solid #DDD3FA;background:#FAF8FF;border-radius:15px;padding:14px"><div style="display:flex;justify-content:space-between;gap:12px"><div><span class="badge violet">แนะนำอันดับ 1</span><h3 style="font-size:17px;margin:7px 0 2px">${best.zone.name}</h3><p>${best.peak} โดยเฉพาะช่วง ${vendorProfile.peakTime}</p></div><b style="font-size:28px;color:#6D28D9">${best.score}<small style="font-size:11px">/100</small></b></div><div class="checks" style="margin:12px 0 0"><span class="check">${I('check-circle')} <span>${best.productFit?'หมวดสินค้าในโปรไฟล์ตรงกับ Zone นี้':'เป็นจุดเด่นที่ผู้เข้าชมเดินผ่านมาก'}</span></span><span class="check">${I('footprints')} <span>Traffic score ${best.traffic}/100 จากทางเดินหลักและจุดบริการ</span></span><span class="check">${I('store')} <span>เหมาะกับช่วงเวลาขายดีของร้านคุณ</span></span></div></div><div style="display:grid;gap:7px">${ranked.slice(1).map((r,i)=>`<div class="summary-line"><span>${i+2}. ${r.zone.short}<small style="display:block;color:var(--muted)">${r.peak}</small></span><b>${r.score}/100</b></div>`).join('')}</div><div class="modal-actions"><button class="btn outline" onclick="closeModal()">ปิด</button><button class="btn primary" onclick="closeModal();changeBookingZone('${best.zone.name}')">เลือกโซนแนะนำ ${I('arrow-right')}</button></div></section></div>`;if(window.lucide)lucide.createIcons()}
    function applyZoneBoothRecommendation(zoneName,boothName){selectedZone=zoneName;selectedBooth=boothName;closeModal();go('confirm')}
    function openZoneRecommendation(){let ranked=zoneRanking(),best=ranked[0],boothName=best.zone.prefix+'05',boothScore=Math.min(99,best.score+1);document.getElementById('modal').innerHTML=`<div class="modal-back" onclick="closeModal(event)"><section class="modal" onclick="event.stopPropagation()"><div class="modal-head"><div><span class="eyebrow">SMART ZONE + BOOTH MATCH</span><h2>พื้นที่ที่เหมาะกับร้านคุณที่สุด</h2></div><button class="close" aria-label="ปิด" onclick="closeModal()">${I('x')}</button></div><p style="margin-top:7px">อิงจากโปรไฟล์ <b>${vendorProfile.business}</b> · ${vendorProfile.category}, ช่วงเวลาขายดี และเส้นทางการเดินในงาน</p><div style="margin:16px 0;border:1px solid #DDD3FA;background:#FAF8FF;border-radius:15px;padding:14px"><div style="display:flex;justify-content:space-between;gap:12px"><div><span class="badge violet">แนะนำให้ล็อก</span><h3 style="font-size:17px;margin:7px 0 2px">${best.zone.name} · Booth ${boothName}</h3><p>${best.peak} โดยเฉพาะช่วง ${vendorProfile.peakTime}</p></div><b style="font-size:28px;color:#6D28D9">${boothScore}<small style="font-size:11px">/100</small></b></div><div class="checks" style="margin:12px 0 0"><span class="check">${I('check-circle')} <span>${best.productFit?'ประเภทสินค้าในโปรไฟล์ตรงกับ Zone นี้':'Zone นี้อยู่ในกลุ่มผู้ชมที่มีโอกาสสนใจสินค้า'}</span></span><span class="check">${I('footprints')} <span>Booth ${boothName} อยู่แถวหน้าติดทางเดินหลัก เชื่อมทางเข้าและจุดบริการ</span></span><span class="check">${I('trending-up')} <span>Traffic score ${best.traffic}/100 เหมาะกับช่วงเวลาที่ยอดขายของร้านสูงสุด</span></span><span class="check">${I('store')} <span>มีพื้นที่ว่างจริงและอุปกรณ์ตามความต้องการของร้าน</span></span></div></div><div class="policy"><b>${I('timer')} จะ Hold Booth ให้ 5 นาที</b><p>เมื่อกดล็อก Booth ระบบจะเข้าสู่หน้ายืนยันและเริ่มเวลาล็อกชั่วคราวก่อนสร้างรายการจอง</p></div><div style="display:grid;gap:7px;margin-top:12px">${ranked.slice(1).map((r,i)=>`<div class="summary-line"><span>${i+2}. ${r.zone.short}<small style="display:block;color:var(--muted)">${r.peak}</small></span><b>${r.score}/100</b></div>`).join('')}</div><div class="modal-actions"><button class="btn outline" onclick="closeModal();changeBookingZone('${best.zone.name}')">ดู Zone นี้ก่อน</button><button class="btn primary" onclick="applyZoneBoothRecommendation('${best.zone.name}','${boothName}')">${I('lock-keyhole')}ล็อก Booth แนะนำ</button></div></section></div>`;if(window.lucide)lucide.createIcons()}
    function openEventTerms(){document.getElementById('modal').innerHTML=`<div class="modal-back" onclick="closeModal(event)"><section class="modal" onclick="event.stopPropagation()"><div class="modal-head"><div><span class="eyebrow">EVENT AGREEMENT</span><h2>กติกาและข้อตกลงการจอง</h2></div><button class="close" aria-label="ปิด" onclick="closeModal()">${I('x')}</button></div><p style="margin-top:7px">โปรดอ่านก่อนเข้าสู่แผนผังและเลือก Booth ของ ${selectedEvent.name}</p><div class="checks" style="margin:18px 0 4px"><label class="check"><input type="checkbox" checked><span><b>กติกา Event</b><br>ยอมรับเวลาเข้า–ออกพื้นที่ และปฏิบัติตามเงื่อนไขของผู้จัดงาน</span></label><label class="check"><input type="checkbox" checked><span><b>สินค้าถูกกฎหมาย</b><br>สินค้าต้องอยู่ในหมวดที่ Zone นั้นอนุญาต</span></label><label class="check"><input type="checkbox" checked><span><b>นโยบายยกเลิกและคืนเงิน</b><br>หลังยืนยันการจอง การติดต่อคืนเงินดำเนินการผ่าน Support</span></label></div><div class="policy"><b>${I('shield-check')} ข้อตกลงสำหรับผู้ขาย</b><p>การกด “ยอมรับทั้งหมด” คือการยอมรับข้อตกลงทั้ง 3 ข้อก่อนเริ่มเลือกพื้นที่</p></div><div class="modal-actions"><button class="btn outline" onclick="closeModal()">ปิด</button><button class="btn primary" onclick="closeModal();go('zones')">${I('check-check')}ยอมรับทั้งหมด</button></div></section></div>`;if(window.lucide)lucide.createIcons()}
    function zones(){let z=currentZone(),cells=floorBoothCells(z),plan=selectedEvent.id==='agri'?`<div class="plan-scroll"><img class="plan-image" src="assets/sut-agri-fair-plan.png" alt="แผนผังงานเกษตร มทส. 2569"></div>`:`<div class="plan-scroll"><div class="site-plan"><div class="plan-entry">${I('log-in')} ทางเข้า <small>· จุดลงทะเบียน</small></div>${selectedEvent.zones.map((zone,index)=>`<button class="plan-zone zone-${index} ${zone.theme} ${selectedZone===zone.name?'focused':''}" onclick="chooseZone('${zone.name}')"><span class="plan-count">${zone.free} ว่าง</span><h3>${zone.name}</h3><p>${zone.products}</p><div class="mini-booths">${planSlots(zone)}</div></button>`).join('')}<div class="plan-lane">ทางเดินกลาง 4 เมตร</div><div class="plan-service"><span>${I('circle-parking')} ที่จอดรถ</span><span>${I('accessibility')} สิ่งอำนวยความสะดวก</span><span>${I('cross')} ปฐมพยาบาล</span><span>${I('info')} ประชาสัมพันธ์</span><span>${I('bath')} ห้องน้ำ</span></div><div class="plan-exit">${I('log-out')} ทางออก <small>· จุดรับส่ง</small></div></div></div>`;return shell(`<div class="page">${title('EVENT FLOOR PLAN',selectedEvent.name,'อ่านกติกาแล้ว เลือก Zone และเลือก Booth ได้จากหน้าจอเดียว',`<button class="btn outline" onclick="go('detail')">${I('arrow-left')}กลับ Event</button>`)}<section class="map-layout"><div class="surface map-card"><div class="map-toolbar"><div><h2>แผนผังพื้นที่และบูธ</h2><p style="margin:2px 0 0;color:var(--muted);font-size:12px">${selectedEvent.id==='agri'?'แผนผังงานเกษตร มทส. ตามภาพจริง':'กดโซนบนผัง หรือเลือกจาก dropdown ด้านล่าง'}</p></div><button class="btn secondary small" onclick="chooseZone(selectedEvent.zones[0].name);showToast('แนะนำโดยระบบสำรอง: '+selectedEvent.zones[0].short)">${I('sparkles')}แนะนำโซน</button></div><div class="legend">${status('available')}<span class="badge neutral">${I('mouse-pointer-click')} เลือก Zone ด้านล่าง</span><span class="badge neutral">${I('map-pin')} จุดบริการผู้เข้าชม</span></div>${plan}<section style="margin-top:20px;padding-top:18px;border-top:1px solid var(--line)"><div class="map-toolbar"><div><h2>เลือก Booth ใน ${z.short}</h2><p style="margin:2px 0 0;color:var(--muted);font-size:12px">เปลี่ยน Zone แล้วบูธและรหัสตำแหน่งจะอัปเดตทันที</p></div><span class="badge available">${z.free} บูธว่าง</span></div><div class="field" style="max-width:390px"><label>เลือก Zone เพื่อจอง</label><select aria-label="เลือก Zone เพื่อจอง" onchange="changeBookingZone(this.value)">${selectedEvent.zones.map(zone=>`<option value="${zone.name}" ${zone.name===selectedZone?'selected':''}>${zone.short} · ${zone.products}</option>`).join('')}</select></div><div class="legend">${status('available')}${status('booked')}${status('hold')}${status('payment')}${status('disabled')}</div><div class="booth-grid">${cells.map(x=>booth(...x)).join('')}</div></section></div><aside class="surface map-side"><span class="eyebrow">SELECTED ZONE</span><h2>${z.name}</h2><p>${z.desc}</p><div class="info-list"><div class="info-line"><span>บูธว่าง</span><b>${z.free} บูธ</b></div><div class="info-line"><span>ราคา</span><b>${z.price}</b></div><div class="info-line"><span>บูธทั้งหมด</span><b>${z.total} บูธ</b></div><div class="info-line"><span>ขนาดบูธ</span><b>3 × 3 ม.</b></div></div><div class="policy"><b>วิธีเลือกบูธ</b><p>แตะ Booth สีเขียวเพื่ออ่านรายละเอียด แล้วกด Select Booth เพื่อไปต่อ</p></div></aside></section></div>`) }
    function openBooth(name){let z=currentZone();selectedBooth=name;document.getElementById('modal').innerHTML=`<div class="modal-back" onclick="closeModal(event)"><section class="modal" onclick="event.stopPropagation()"><div class="modal-head"><div><span class="eyebrow">AVAILABLE BOOTH</span><h2>Booth ${name}</h2></div><button class="close" onclick="closeModal()">${I('x')}</button></div><p>${selectedEvent.name} · ${z.short} · Tier S</p><div class="info-list"><div class="info-line"><span>ราคา</span><b style="font-size:18px;color:#6633C4">${money(price)}</b></div><div class="info-line"><span>ระดับพื้นที่</span><b>Tier ${tier}</b></div><div class="info-line"><span>ขนาด</span><b>3 × 3 เมตร</b></div><div class="info-line"><span>วันที่ใช้งาน</span><b>${selectedEvent.date}</b></div></div><h3>สิ่งอำนวยความสะดวก</h3><p>${z.facility}</p><h3>สินค้าที่อนุญาต</h3><p>${z.products}</p><h3>ติดต่อผู้จัดงาน</h3><p>${selectedEvent.contact}</p><div class="modal-actions"><button class="btn outline" onclick="closeModal()">Close</button><button class="btn primary" onclick="closeModal();go('booking')">Select Booth ${I('arrow-right')}</button></div></section></div>`;if(window.lucide)lucide.createIcons()}
