    function openNotifications(){document.getElementById('modal').innerHTML=`<div class="modal-back" onclick="closeModal(event)"><section class="modal notification-modal" onclick="event.stopPropagation()"><div class="modal-head"><div><span class="eyebrow">NOTIFICATIONS</span><h2>การแจ้งเตือน</h2></div><button class="close" onclick="closeModal()">${I('x')}</button></div><div class="notification-list"><button onclick="closeModal();openEvent('agri')"><span class="notify-icon violet-bg">${I('sparkles')}</span><span><b>มี Event ใหม่ที่เหมาะกับร้านคุณ</b><small>มทส เกษตรแฟร์ 2569 เปิดรับจองแล้ว · 5 นาทีที่แล้ว</small></span><i class="unread-dot"></i></button><button onclick="closeModal();go('payment')"><span class="notify-icon blue-bg">${I('credit-card')}</span><span><b>รายการจองรอชำระเงิน</b><small>SUT Green Market · Booth A15 · 1 ชั่วโมงที่แล้ว</small></span><i class="unread-dot"></i></button><button onclick="closeModal();go('ticket')"><span class="notify-icon green-bg">${I('message-circle')}</span><span><b>ผู้จัดงานตอบกลับคำร้องแล้ว</b><small>SUP-104 · ขอคืนเงินหลังยกเลิกการจอง</small></span></button></div><div class="modal-actions"><button class="btn outline" onclick="showToast('ทำเครื่องหมายว่าอ่านแล้วทั้งหมด');closeModal()">อ่านทั้งหมดแล้ว</button><button class="btn primary" onclick="closeModal();go('bookings')">ดูการจองของฉัน</button></div></section></div>`;if(window.lucide)lucide.createIcons()}
    function openEditProfile(){document.getElementById('modal').innerHTML=`<div class="modal-back" onclick="closeModal(event)"><section class="modal" onclick="event.stopPropagation()"><div class="modal-head"><div><span class="eyebrow">EDIT PROFILE</span><h2>แก้ไขโปรไฟล์ร้านค้า</h2></div><button class="close" onclick="closeModal()">${I('x')}</button></div><div class="form-grid" style="margin-top:17px"><div class="field"><label>ชื่อร้าน</label><input id="editBusiness" value="${vendorProfile.business}"></div><div class="field"><label>ประเภทธุรกิจ</label><select id="editCategory"><option ${vendorProfile.category==='อาหารและเครื่องดื่ม'?'selected':''}>อาหารและเครื่องดื่ม</option><option>เสื้อผ้าและแฟชั่น</option><option>สินค้าเกษตร</option><option>งานฝีมือและ OTOP</option></select></div><div class="field"><label>เบอร์โทรศัพท์</label><input id="editPhone" value="${vendorProfile.phone}"></div><div class="field"><label>อีเมล</label><input id="editEmail" type="email" value="${vendorProfile.email}"></div></div><div class="field" style="margin-top:13px"><label>ช่วงเวลาขายดี</label><input id="editPeak" value="${vendorProfile.peakTime}"></div><div class="modal-actions"><button class="btn outline" onclick="closeModal()">ยกเลิก</button><button class="btn primary" onclick="saveProfile()">${I('save')}บันทึกการเปลี่ยนแปลง</button></div></section></div>`;if(window.lucide)lucide.createIcons()}
    function saveProfile(){vendorProfile.business=document.getElementById('editBusiness').value.trim()||vendorProfile.business;vendorProfile.category=document.getElementById('editCategory').value;vendorProfile.phone=document.getElementById('editPhone').value.trim()||vendorProfile.phone;vendorProfile.email=document.getElementById('editEmail').value.trim()||vendorProfile.email;vendorProfile.peakTime=document.getElementById('editPeak').value.trim()||vendorProfile.peakTime;closeModal();render();showToast('บันทึกโปรไฟล์เรียบร้อยแล้ว')}
