    function showToast(message){clearTimeout(toastTimer);document.getElementById('toast').innerHTML=`<div class="toast">${I('check-circle')} ${message}</div>`;if(window.lucide)lucide.createIcons();toastTimer=setTimeout(()=>document.getElementById('toast').innerHTML='',3300)}
    let countdown;function startTimer(){clearInterval(countdown);let remaining=300;const out=document.getElementById('timer');countdown=setInterval(()=>{remaining--;if(out)out.textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`;if(remaining<=0){clearInterval(countdown);showToast('หมดเวลา Hold แล้ว กรุณาเลือกบูธใหม่');go('booths')}},1000)}

