    function requireLogin(action){
      if(isLoggedIn){ action(); return; }
      pendingAuthAction=action;
      openAuthModal('login');
    }
    function openAuthModal(mode='login'){
      const isRegister=mode==='register', isForgot=mode==='forgot';
      document.getElementById('modal').innerHTML=`<div class="modal-back" onclick="closeModal(event)"><section class="modal auth-modal" onclick="event.stopPropagation()"><div class="modal-head"><div><span class="eyebrow">SPACELINK ACCOUNT</span><h2>${isRegister?'สมัครสมาชิกผู้ขาย':isForgot?'ลืมรหัสผ่าน':'เข้าสู่ระบบก่อนจองพื้นที่'}</h2></div><button class="close" onclick="closeModal()">${I('x')}</button></div>
      ${isRegister?`<div class="profile-upload"><div class="profile-upload-preview">${I('store')}</div><div><b>โปรไฟล์ร้านค้า</b><p>เพิ่มรูปโลโก้หรือภาพร้าน เพื่อแสดงบนบูธที่จอง</p><button class="btn secondary small" onclick="showToast('เลือกไฟล์รูปโปรไฟล์แล้ว')">${I('image-plus')}เลือกรูป</button></div></div><div class="form-grid"><div class="field"><label>ชื่อร้าน</label><input id="reg-shop" placeholder="เช่น อรุณ คาเฟ่"></div><div class="field"><label>ชื่อ–นามสกุล</label><input id="reg-owner" placeholder="ชื่อผู้ติดต่อ"></div><div class="field"><label>เบอร์โทรศัพท์</label><input id="reg-phone" placeholder="08x-xxx-xxxx"></div><div class="field"><label>อีเมล</label><input id="reg-email" type="email" placeholder="name@example.com"></div><div class="field full"><label>รายละเอียดร้าน</label><textarea id="reg-desc" rows="3" placeholder="แนะนำร้านของคุณ"></textarea></div><div class="field full"><label>สินค้าที่ขาย</label><textarea id="reg-products" rows="2" placeholder="ระบุสินค้า/บริการหลัก"></textarea></div><div class="field"><label>รหัสผ่าน</label><input type="password" placeholder="อย่างน้อย 8 ตัวอักษร"></div><div class="field"><label>ยืนยันรหัสผ่าน</label><input type="password" placeholder="กรอกรหัสผ่านอีกครั้ง"></div></div>`:isForgot?`<p style="margin-top:10px">เลือกช่องทางรับรหัสยืนยันเพื่อสร้างรหัสผ่านใหม่</p><div class="auth-choice"><label><input type="radio" name="verify" checked> ${I('mail')} ยืนยันผ่านอีเมล</label><label><input type="radio" name="verify"> ${I('phone')} ยืนยันผ่านเบอร์โทรศัพท์</label></div><div class="field"><label>อีเมลหรือเบอร์โทร</label><input placeholder="กรอกข้อมูลที่ใช้สมัคร"></div>`:`<div class="field" style="margin-top:18px"><label>อีเมลหรือเบอร์โทรศัพท์</label><input id="login-id" value="arun@example.com"></div><div class="field" style="margin-top:12px"><label>รหัสผ่าน</label><input type="password" value="12345678"></div><button class="btn ghost small auth-forgot" onclick="openAuthModal('forgot')">ลืมรหัสผ่าน?</button>`}
      <div class="modal-actions auth-actions">${isRegister?`<button class="btn outline" onclick="openAuthModal('login')">มีบัญชีแล้ว</button><button class="btn primary" onclick="completeRegister()">สมัครสมาชิก</button>`:isForgot?`<button class="btn outline" onclick="openAuthModal('login')">กลับเข้าสู่ระบบ</button><button class="btn primary" onclick="showToast('ส่งรหัสยืนยันแล้ว');openAuthModal('login')">ส่งรหัสยืนยัน</button>`:`<button class="btn outline" onclick="openAuthModal('register')">สมัครสมาชิก</button><button class="btn primary" onclick="completeLogin()">เข้าสู่ระบบ ${I('log-in')}</button>`}</div></section></div>`;
      if(window.lucide)lucide.createIcons();
    }
    function completeLogin(){isLoggedIn=true;closeModal();showToast('เข้าสู่ระบบสำเร็จ');const a=pendingAuthAction;pendingAuthAction=null;if(a)a();else render()}
    function completeRegister(){
      vendorProfile.business=document.getElementById('reg-shop')?.value||vendorProfile.business;
      vendorProfile.ownerName=document.getElementById('reg-owner')?.value||vendorProfile.ownerName;
      vendorProfile.phone=document.getElementById('reg-phone')?.value||vendorProfile.phone;
      vendorProfile.email=document.getElementById('reg-email')?.value||vendorProfile.email;
      vendorProfile.description=document.getElementById('reg-desc')?.value||vendorProfile.description;
      vendorProfile.products=document.getElementById('reg-products')?.value||vendorProfile.products;
      isLoggedIn=true;closeModal();showToast('สมัครสมาชิกและเข้าสู่ระบบแล้ว');const a=pendingAuthAction;pendingAuthAction=null;if(a)a();else go('profile');
    }

