    function mapsUrl(query){return 'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(query)}
    function openGps(query){window.open(mapsUrl(query),'_blank','noopener,noreferrer')}
    function detail(){
      const gps=eventGpsPoints();
      return shell(`<div class="page event-detail-gradient">${title('EVENT DETAIL',selectedEvent.name,selectedEvent.date+' · '+selectedEvent.where,`<button class="btn gradient-primary" onclick="requireLogin(()=>openEventTerms())">เลือกโซนและบูธ ${I('map')}</button>`)}
      <section class="detail-banner gradient-hero" style="background-image:linear-gradient(110deg,rgba(42,16,89,.94),rgba(124,58,237,.70),rgba(14,165,233,.18)),url('${selectedEvent.cover}')"><div><span class="badge glass-badge">กำลังเปิดจอง</span><h1>${selectedEvent.name}</h1><p>${I('calendar-days')} ${selectedEvent.date} &nbsp; ${I('map-pin')} ${selectedEvent.where}</p><div class="hero-action-row"><button class="btn glass-button" onclick="openGps('${selectedEvent.where.replaceAll("'","\\'")}')">${I('navigation')} นำทางไปงาน</button><button class="btn glass-button" onclick="openMapViewer()">${I('maximize-2')} ดูแผนที่</button></div></div></section>
      <section class="detail-layout gradient-detail-layout"><div class="surface gradient-panel"><div class="overview-head"><div><span class="eyebrow">EVENT OVERVIEW</span><h2>เกี่ยวกับ Event นี้</h2></div><button class="btn gradient-primary overview-book-btn" onclick="requireLogin(()=>openEventTerms())">${I('map')} จองพื้นที่ ${I('arrow-right')}</button></div><p>${selectedEvent.desc}</p><div class="event-highlights">${eventHighlights().map((item,i)=>`<div class="highlight-item gradient-highlight g${i%3}"><span>${I(item.icon)}</span><div><b>${item.title}</b><p>${item.text}</p></div></div>`).join('')}</div><h2 style="margin-top:25px">โซนและพื้นที่ว่าง</h2><p>เลือกโซนที่เหมาะกับประเภทสินค้า พร้อมตรวจสอบจำนวนบูธว่างก่อนจอง</p><div class="zone-preview gradient-zones">${selectedEvent.zones.map((z,i)=>`<div class="zone-pill zone-gradient-${i%4}">${z.short}<small>${z.free} / ${z.total} บูธว่าง</small></div>`).join('')}</div></div><aside class="surface gradient-panel event-info-card"><span class="eyebrow">QUICK INFO</span><h2>ข้อมูลงาน</h2><div class="info-list"><div class="info-line"><span>${I('clock-3')}เวลา</span><b>${selectedEvent.time}</b></div><div class="info-line"><span>${I('building-2')}ผู้จัดงาน</span><b>${selectedEvent.org}</b></div><div class="info-line"><span>${I('phone')}ติดต่อ</span><b>${selectedEvent.contact}</b></div><div class="info-line"><span>${I('store')}บูธคงเหลือ</span><b>${selectedEvent.booths} / ${selectedEvent.total}</b></div></div><button class="btn gps-main" onclick="openGps('${selectedEvent.where.replaceAll("'","\\'")}')">${I('navigation')} เปิด GPS ไปยังสถานที่จัดงาน</button><div class="policy gradient-policy"><b>ข้อกำหนดสินค้า</b><p>สินค้าต้องถูกกฎหมายและอยู่ในหมวดที่แต่ละโซนอนุญาต</p></div><div class="policy gradient-policy"><b>การยกเลิกและคืนเงิน</b><p>ติดต่อผู้จัดงานผ่าน Support ตามเงื่อนไขของ Event</p></div></aside></section>
      <section class="surface gps-section"><div class="section-heading"><div><span class="eyebrow">GPS NAVIGATION</span><h2>เดินทางไปยังแต่ละจุด</h2><p>เลือกจุดหมายแล้วเปิดเส้นทางด้วย Google Maps ได้ทันที</p></div></div><div class="gps-grid">${gps.map((x,i)=>`<button class="gps-card gps-${i%4}" onclick="openGps('${x[1].replaceAll("'","\\'")}')"><span class="gps-icon">${I(x[2])}</span><span><b>${x[0]}</b><small>${x[1]}</small></span>${I('route')}</button>`).join('')}</div></section>
      <section class="event-map-clean gradient-map-section"><div class="event-map-head aligned-map-head"><div class="map-title-block"><span class="eyebrow">${I('map')} EVENT MAP</span><h2>แผนที่ภายในงาน</h2><p>แผนที่เฉพาะของ ${selectedEvent.name} พร้อมจุดเข้า–ออก โซนขาย ห้องน้ำ และพื้นที่จอดรถ</p></div><div class="map-actions"><button class="btn outline" onclick="openMapViewer()">${I('maximize-2')} ขยายแผนที่</button><button class="btn gps-main" onclick="openGps('${selectedEvent.where.replaceAll("'","\\'")}')">${I('navigation')} GPS</button><button class="btn gradient-primary" onclick="requireLogin(()=>openEventTerms())">เลือกบูธ ${I('arrow-right')}</button></div></div><button class="event-map-direct gradient-map-frame" onclick="openMapViewer()" aria-label="ขยายแผนที่ ${selectedEvent.name}"><img src="${selectedEvent.map}" alt="แผนที่ ${selectedEvent.name}"><span class="map-zoom-hint">${I('zoom-in')} คลิกเพื่อขยาย</span></button></section>
      <section class="activity-section"><div class="section-heading"><div><span class="eyebrow">EVENT MOMENTS</span><h2>ภาพกิจกรรมภายในงาน</h2><p>บรรยากาศ โซนสินค้า และกิจกรรมเด่นที่ผู้เข้าร่วมจะได้พบ</p></div></div><div class="activity-grid gradient-gallery">${activityGallery()}</div></section></div>`)
    }

        document.addEventListener('click',()=>document.querySelectorAll('.smart-select.open').forEach(el=>el.classList.remove('open')));
