    // ===== Unified integration: write bookings to the shared store + logout =====
    // Called when the vendor confirms a booking. Each selected booth becomes a
    // PENDING record in the shared localStorage store, which the Admin Console
    // reads and shows in its "Booking Approvals" table.
    function createBookingsAndPay(){
      if(window.SpaceLinkStore && selectedBooths.length){
        selectedBooths.forEach(item=>{
          SpaceLinkStore.addBooking({
            vendor:vendorProfile.business,
            owner:vendorProfile.ownerName,
            event:selectedEvent.name,
            eventId:selectedEvent.id,
            zone:item.zoneShort,
            booth:item.name,
            tier:item.tier,
            amount:item.price,
            date:selectedEvent.date
          });
        });
        showToast('ส่งคำขอจอง '+selectedBooths.length+' บูธ ไปยังผู้ดูแลระบบแล้ว');
        selectedBooths=[];
      }
      go('payment');
    }
    function slLogout(){
      if(window.SpaceLinkStore) SpaceLinkStore.clearSession();
      location.href='../index.html';
    }
